  sleep 5
done

if [[ "${http_status}" != "200" ]]; then
  echo " TIMEOUT"
  aws ecs describe-express-gateway-service \
    --service-arn arn:aws:ecs:${AWS_REGION}:${ACCOUNT_ID}:service/unicorn-store-spring/unicorn-store-spring \
