ws_begin_page 'Custom JRE' 220 'optimize-containers/custom-jre/index.en.md'

ws_run_block 'block-001' 'Changing the source code' 'Change the application code of UnicornController.java to identify the new version of the application deployment:' 30 32 'bash' '' 600 62 219 <<'WS_TEST_BLOCK_220_001'
