sudo ctr -n moby images pull \
  --user "AWS:${SOCI_ECR_PASSWORD}" \
  "${ECR_URI}:04-soci"
printf '%s' "${SOCI_ECR_PASSWORD}" \
  | sudo docker login --username AWS --password-stdin "${ECR_URI%%/*}"
