apiVersion: apps/v1
kind: DaemonSet
metadata:
  name: perf-collector
  namespace: monitoring
  labels:
    app: perf-collector
spec:
  selector:
    matchLabels:
      app: perf-collector
  template:
    metadata:
      labels:
        app: perf-collector
    spec:
      # The target JVM workload is scheduled on this node pool. The collector
      # must run alongside it because discovery and profiling are node-local.
      nodeSelector:
        karpenter.sh/nodepool: workshop
      serviceAccountName: perf-collector
      hostPID: true
      containers:
      - name: perf-collector
        image: ${ECR_URI}:latest
        securityContext:
          runAsUser: 0
          privileged: true
        volumeMounts:
        - name: profiler-host
          mountPath: /var/perf-collector
        env:
        - name: NODE_NAME
          valueFrom:
            fieldRef:
              fieldPath: spec.nodeName
        - name: AWS_REGION
          value: "${AWS_REGION}"
        - name: AWS_S3_BUCKET
          value: "${S3_BUCKET}"
        - name: PERF_COLLECTOR_PLATFORM
          value: "eks"
        - name: PYROSCOPE_URL
          value: "http://pyroscope.monitoring:4040"
        resources:
          requests:
            cpu: "100m"
            memory: "256Mi"
          limits:
            cpu: "500m"
            memory: "512Mi"
      volumes:
      - name: profiler-host
        hostPath:
          path: /var/perf-collector
          type: DirectoryOrCreate
---
apiVersion: v1
kind: ServiceAccount
metadata:
  name: perf-collector
  namespace: monitoring
---
apiVersion: rbac.authorization.k8s.io/v1
kind: ClusterRole
metadata:
  name: perf-collector
rules:
- apiGroups: [""]
  resources: ["pods"]
  verbs: ["list"]
---
apiVersion: rbac.authorization.k8s.io/v1
kind: ClusterRoleBinding
metadata:
  name: perf-collector
subjects:
- kind: ServiceAccount
  name: perf-collector
  namespace: monitoring
roleRef:
  kind: ClusterRole
  name: perf-collector
  apiGroup: rbac.authorization.k8s.io
EOF

