         essential: false,
         linuxParameters: {capabilities: {add: ["SYS_PTRACE"]}},
         environment: [
           {name: "PERF_COLLECTOR_PLATFORM", value: "ecs"},
           {name: "AWS_REGION", value: $region},
           {name: "AWS_S3_BUCKET", value: $bucket},
           {name: "PYROSCOPE_URL", value: $pyroscope}
