BENCHMARK_PID=$!

cleanup_benchmark() {
  if [[ -n "${BENCHMARK_PID:-}" ]]; then
    kill "${BENCHMARK_PID}" 2>/dev/null || true
    wait "${BENCHMARK_PID}" 2>/dev/null || true
    BENCHMARK_PID=""
  fi
}

analyze_under_load() {
  echo "Waiting 60 seconds for steady load ..."
  sleep 60 || return 1

  POD=$(kubectl get pods -n unicorn-store-spring \
    -l app=unicorn-store-spring --field-selector=status.phase=Running \
    -o jsonpath='{.items[0].metadata.name}') || return 1
  [[ -n "${POD}" ]] || return 1

  kubectl run -n monitoring trigger-analyze --rm --attach=true --restart=Never \
    --pod-running-timeout=120s \
    --image=curlimages/curl:latest --quiet -- \
    curl -sS --fail --connect-timeout 10 --max-time 60 -X POST "http://perf-analyzer.monitoring.svc.cluster.local:8080/api/v1/analyze" \
      -H 'Content-Type: application/json' \
      -d "{\"service\":\"unicorn-store-spring\",\"platform\":\"eks\",\"pod\":\"${POD}\",\"reason\":\"under load check\"}"
}

trap cleanup_benchmark INT TERM
if ! analyze_under_load; then
  cleanup_benchmark
  trap - INT TERM
  unset -f analyze_under_load cleanup_benchmark
  return 1
fi
(
  set +o pipefail
  kubectl logs -n monitoring -l app=perf-analyzer --tail=0 -f | awk '
    { print; fflush() }
    / complete: s3:\/\// { exit }
  '
)
if ! wait "${BENCHMARK_PID}"; then
  BENCHMARK_PID=""
  trap - INT TERM
  unset -f analyze_under_load cleanup_benchmark
  return 1
fi
BENCHMARK_PID=""
trap - INT TERM
unset -f analyze_under_load cleanup_benchmark
