ws_run_block 'block-008' 'Enabling Prometheus metrics collection' 'Add the Java application metrics URL to the Prometheus configuration:' 119 172 'bash' 'ecs' 600 156 219 <<'WS_TEST_BLOCK_322_008'
# Get ECS service URL
ECS_URL=$(cat ~/environment/.workshop-svc-url-ecs | tr -d '\n\r ')

# Determine scheme and target
if echo "${ECS_URL}" | grep -q "^https://"; then
  SCHEME="https"
  TARGET="$(echo ${ECS_URL} | sed 's|^https://||;s|/.*||'):443"
else
  SCHEME="http"
  TARGET="$(echo ${ECS_URL} | sed 's|^http://||;s|/.*||'):80"
fi

# Add ECS scrape job to Prometheus config
kubectl get configmap prometheus-server -n monitoring -o yaml > /tmp/prometheus-cm.yaml

yq -i '.data["prometheus.yml"] |= (
  from_yaml
  | .scrape_configs = (
      [.scrape_configs[] | select(.job_name != "ecs-unicorn-store-spring")]
      + [{
        "job_name": "ecs-unicorn-store-spring",
        "scheme": "'"${SCHEME}"'",
        "metrics_path": "/actuator/prometheus",
        "scrape_interval": "15s",
        "tls_config": {"insecure_skip_verify": true},
        "static_configs": [{"targets": ["'"${TARGET}"'"]}]
      }]
    )
  | to_yaml
)' /tmp/prometheus-cm.yaml

kubectl apply -f /tmp/prometheus-cm.yaml
rm /tmp/prometheus-cm.yaml

# Restart Prometheus to pick up new config
kubectl rollout restart deployment prometheus-server -n monitoring
kubectl rollout status deployment prometheus-server -n monitoring --timeout=300s

# Allow Lambda to reach ECS tasks for thread dump collection
VPC_ID=$(aws ec2 describe-vpcs --filters "Name=tag:Name,Values=workshop-vpc" \
  --query 'Vpcs[0].VpcId' --output text --no-cli-pager)
LAMBDA_SG=$(aws ec2 describe-security-groups --filters "Name=vpc-id,Values=${VPC_ID}" \
  "Name=group-name,Values=workshop-thread-dump-lambda-sg" \
  --query 'SecurityGroups[0].GroupId' --output text --no-cli-pager)
ECS_SG=$(aws ec2 describe-security-groups --filters "Name=vpc-id,Values=${VPC_ID}" \
  --query 'SecurityGroups[?contains(GroupName, `unicorn-store-spring`) && !contains(GroupName, `alb`)].GroupId' \
  --output text --no-cli-pager | head -1)

if [[ -n "${LAMBDA_SG}" && "${LAMBDA_SG}" != "None" && -n "${ECS_SG}" && "${ECS_SG}" != "None" ]]; then
  aws ec2 authorize-security-group-ingress --group-id "${ECS_SG}" \
    --protocol tcp --port 8080 --source-group "${LAMBDA_SG}" --no-cli-pager 2>/dev/null || true
fi

echo "✅ ECS metrics endpoint added: ${ECS_URL}/actuator/prometheus"
