mkdir -p ~/environment/ai-jvm-analyzer/k8s/
cat <<EOF > ~/environment/ai-jvm-analyzer/k8s/deployment.yaml
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ai-jvm-analyzer
  namespace: monitoring
  labels:
    app: ai-jvm-analyzer
spec:
  replicas: 1
  selector:
    matchLabels:
      app: ai-jvm-analyzer
  template:
    metadata:
      labels:
        app: ai-jvm-analyzer
    spec:
      serviceAccountName: ai-jvm-analyzer
      containers:
      - name: ai-jvm-analyzer
        resources:
          requests:
            cpu: "1"
            memory: "2Gi"
          limits:
            cpu: "1"
            memory: "2Gi"
        image: ${ECR_URI}:latest
        ports:
        - containerPort: 8080
        env:
        - name: AWS_REGION
          value: "${AWS_REGION:-us-east-1}"
        - name: AWS_S3_BUCKET
          value: "${S3_BUCKET}"
        - name: SPRING_AI_BEDROCK_CONVERSE_CHAT_OPTIONS_MODEL
          value: "global.anthropic.claude-sonnet-4-5-20250929-v1:0"
        - name: SPRING_AI_BEDROCK_CONVERSE_CHAT_OPTIONS_MAX_TOKENS
          value: "10000"
        - name: GITHUB_REPO_URL
          value: "https://api.github.com/repos/aws-samples/java-on-aws"
        - name: GITHUB_REPO_PATH
          value: "apps/unicorn-store-spring"
        - name: FLAMEGRAPH_INCLUDE
          value: ".*unicorn.*"
        readinessProbe:
          httpGet:
            path: /actuator/health
            port: 8080
          initialDelaySeconds: 30
          periodSeconds: 10
        livenessProbe:
          httpGet:
            path: /actuator/health
            port: 8080
          initialDelaySeconds: 60
          periodSeconds: 30
---
apiVersion: v1
kind: Service
metadata:
  name: ai-jvm-analyzer
  namespace: monitoring
  labels:
    app: ai-jvm-analyzer
spec:
  selector:
    app: ai-jvm-analyzer
  ports:
  - port: 80
    targetPort: 8080
    protocol: TCP
  type: ClusterIP
---
apiVersion: v1
kind: ServiceAccount
metadata:
  name: ai-jvm-analyzer
  namespace: monitoring
EOF

kubectl apply -f ~/environment/ai-jvm-analyzer/k8s/deployment.yaml
kubectl wait deployment ai-jvm-analyzer -n monitoring --for condition=Available=True --timeout=300s
