ws_run_block 'block-002' 'Updating the deployment' 'Add Kubernetes metadata via Downward API and OTEL endpoint overrides:' 43 63 'bash' '' 600 199 219 <<'WS_TEST_BLOCK_424_002'
cd ~/environment/unicorn-store-spring

# Add K8S_NAMESPACE env var with Downward API
yq eval '.spec.template.spec.containers[0].env += [{"name": "K8S_NAMESPACE", "valueFrom": {"fieldRef": {"fieldPath": "metadata.namespace"}}}]' \
  -i k8s/deployment.yaml

# Add K8S_POD_NAME env var with Downward API
yq eval '.spec.template.spec.containers[0].env += [{"name": "K8S_POD_NAME", "valueFrom": {"fieldRef": {"fieldPath": "metadata.name"}}}]' \
  -i k8s/deployment.yaml

# Add OTEL_RESOURCE_ATTRIBUTES for trace correlation
yq eval '.spec.template.spec.containers[0].env += [{"name": "OTEL_RESOURCE_ATTRIBUTES", "value": "k8s.namespace.name=$(K8S_NAMESPACE),k8s.pod.name=$(K8S_POD_NAME)"}]' \
  -i k8s/deployment.yaml

# Override traces endpoint to CloudWatch agent addon
yq eval '.spec.template.spec.containers[0].env += [{"name": "OTEL_EXPORTER_OTLP_TRACES_ENDPOINT", "value": "http://cloudwatch-agent.amazon-cloudwatch:4316/v1/traces"}]' \
  -i k8s/deployment.yaml

# Override Application Signals endpoint to CloudWatch agent addon
yq eval '.spec.template.spec.containers[0].env += [{"name": "OTEL_AWS_APPLICATION_SIGNALS_EXPORTER_ENDPOINT", "value": "http://cloudwatch-agent.amazon-cloudwatch:4316/v1/metrics"}]' \
  -i k8s/deployment.yaml
WS_TEST_BLOCK_424_002

