ws_run_block 'block-003' 'Creating the task definition' 'Create a new task definition with the CloudWatch agent sidecar:' 52 133 'json' '' 600 205 219 <<'WS_TEST_BLOCK_443_003'
cat <<EOF > /tmp/task-def.json
{
  "family": "unicorn-store-spring-unicorn-store-spring",
  "networkMode": "awsvpc",
  "requiresCompatibilities": ["FARGATE"],
  "cpu": "1024",
  "memory": "2048",
  "executionRoleArn": "arn:aws:iam::${ACCOUNT_ID}:role/service-role/unicornstore-ecs-task-execution-role",
  "taskRoleArn": "arn:aws:iam::${ACCOUNT_ID}:role/service-role/unicornstore-ecs-task-role",
  "containerDefinitions": [
    {
      "name": "Main",
      "image": "${ACCOUNT_ID}.dkr.ecr.${AWS_REGION}.amazonaws.com/unicorn-store-spring:latest",
      "cpu": 0,
      "essential": true,
      "portMappings": [
        {
          "containerPort": 8080,
          "hostPort": 8080,
          "protocol": "tcp",
          "name": "main-8080-tcp"
        }
      ],
      "environment": [
        {
          "name": "OTEL_RESOURCE_ATTRIBUTES",
          "value": "deployment.environment=ecs:unicorn-store-spring"
        }
      ],
      "secrets": [
        {
          "name": "SPRING_DATASOURCE_PASSWORD",
          "valueFrom": "${DB_SECRET_ARN}:password::"
        },
        {
          "name": "SPRING_DATASOURCE_URL",
          "valueFrom": "${DB_CONNECTION_ARN}"
        },
        {
          "name": "SPRING_DATASOURCE_USERNAME",
          "valueFrom": "${DB_SECRET_ARN}:username::"
        }
      ],
      "logConfiguration": {
        "logDriver": "awslogs",
        "options": {
          "awslogs-group": "/aws/ecs/unicorn-store-spring",
          "awslogs-region": "${AWS_REGION}",
          "awslogs-stream-prefix": "ecs"
        }
      },
      "dependsOn": [
        {
          "containerName": "cloudwatch-agent",
          "condition": "START"
        }
      ]
    },
    {
      "name": "cloudwatch-agent",
      "image": "public.ecr.aws/cloudwatch-agent/cloudwatch-agent:latest",
      "cpu": 0,
      "essential": true,
      "environment": [
        {
          "name": "CW_CONFIG_CONTENT",
          "value": "{\"traces\":{\"traces_collected\":{\"application_signals\":{}}},\"logs\":{\"metrics_collected\":{\"application_signals\":{}}}}"
        }
      ],
      "logConfiguration": {
        "logDriver": "awslogs",
        "options": {
          "awslogs-group": "/ecs/cloudwatch-agent",
          "awslogs-create-group": "true",
          "awslogs-region": "${AWS_REGION}",
          "awslogs-stream-prefix": "ecs"
        }
      }
    }
  ]
}
EOF
