ws_run_block 'block-001' 'Installing docker buildx' 'Install the buildx plugin and configure QEMU emulation:' 27 35 'bash' '' 600 209 219 <<'WS_TEST_BLOCK_510_001'
BUILDX_VERSION=$(curl --silent "https://api.github.com/repos/docker/buildx/releases/latest" \
  | jq -r .tag_name)
curl -sS -JLO \
  "https://github.com/docker/buildx/releases/download/${BUILDX_VERSION}/buildx-${BUILDX_VERSION}.linux-amd64"
mkdir -p ~/.docker/cli-plugins
mv "buildx-${BUILDX_VERSION}.linux-amd64" ~/.docker/cli-plugins/docker-buildx
chmod +x ~/.docker/cli-plugins/docker-buildx
docker run --privileged --rm tonistiigi/binfmt --install all
docker buildx create --use --driver=docker-container
WS_TEST_BLOCK_510_001

ws_run_block 'block-002' 'Changing the source code' 'Change the application code to identify the new version:' 43 45 'bash' '' 600 210 219 <<'WS_TEST_BLOCK_510_002'
cd ~/environment/unicorn-store-spring
